for k,z,e in [('prev','← 回退一天','← Rewind one day'),('next','处理下一天 →','Process next day →'),('reset','回到第 0 天','Return to day 0'),('end','处理到末日','Process to the end'),('position','已处理天数','Processed days'),('ledger','累计现金账本','Cumulative cash ledger'),('day','天','Day'),('price','价格','Price'),('state','状态','State'),('old','昨日','Yesterday'),('candidate','今天动作候选','Action today'),('new','今日 = max','Today = max'),('decision','选择','Decision'),('keep','保持','Keep'),('improve','更新 ↑','Improve ↑'),('tie','持平 =','Tie ='),('noDay','尚未处理价格；下表是初始条件。','No price processed yet; the table shows initial conditions.'),('progress','已处理 {day}/{n} 天；当前最大已结算利润 s2 = {profit}。','Processed {day}/{n} days; current maximum realized profit s2 = {profit}.'),('dayNote','刚处理第 {day} 天，价格 {p}。所有动作候选读取昨日状态。','Just processed day {day} at price {p}. Every action candidate reads yesterday’s state.'),('pricesLabel','每日价格，按天排列；箭头指向刚处理的价格。','Daily prices in day order; the arrow marks the last processed price.'),('current','← 当前','← current'),('future','待处理','Pending'),('done','已处理','Processed')]:c(k,z,e)
c('quiz','这一步要回答：新的低价能让持股现金变成多少？独立新例 [4,9,2,8]，只处理到第 3 天。h2 表示持股且最多买入两次时的最大现金，不含股票价值。它是多少？先选择，再揭晓；不需要运行上面的实验。','Question: what can a new low price do to holding cash? Fresh case [4,9,2,8], processed only through day 3. h2 is the greatest cash while holding, with at most two buys; it excludes the share’s value. What is h2? Choose before revealing; this exercise is independent of the lab.')
