def p(k,cl='explain'):return f'<p class="{cl}" data-i18n="{k}"></p>'
def section(i,body):return f'<section class="step" id="step{i}" data-step="{i}"><div class="step-inner"><p class="step-kicker">0{i+1}</p><h2 data-i18n="s{i}"></h2>{body}</div></section>'
base='''def baseline(prices):
    n = len(prices)
    best = 0
    for a in range(n):
        for b in range(a + 1, n):
            best = max(best, prices[b] - prices[a])
            for c in range(b + 1, n):
                for d in range(c + 1, n):
                    best = max(best, prices[b] - prices[a]
                               + prices[d] - prices[c])
    return best'''
